import tkinter as tk
from tkinter import ttk

import re
import time


class AutocompleteCombobox(ttk.Combobox):
    def __init__(self, parent=None, prompt_text="Type Here", **kwargs):
        super().__init__(parent, **kwargs)
        self.list_items = kwargs['values']
        self.prompt_text = prompt_text
        self.set(self.prompt_text)
        self.bind('<KeyRelease>', self.autocomplete)
        self.sleeping_thread = None
        self.unbind_class("TCombobox", "<ButtonPress-4>")
        self.unbind_class("TCombobox", "<ButtonPress-5>")
        self.bind('<<ComboboxSelected>>', lambda ev: self.set_default_values())

    def autocomplete(self, event):
        current_text = event.widget.get()
        if current_text == '':
            # if self.sleeping_thread is None:
            #     self.sleeping_thread = threading.Thread(target=self._sleep_to_display_prompt)
            #     self.sleeping_thread.start()
            return

        if current_text == self.prompt_text:
            matching_items = self.list_items
        else:
            matching_items = [
                item for item in self.list_items
                if re.search(current_text, item, re.I)
            ]
        if len(matching_items) > 1:
            self.configure(values=matching_items)
            self.icursor(tk.END)
            self.select_range(len(current_text), tk.END)
        else:
            self.configure(values=self.list_items)

    def set_items(self, items):
        self.list_items = items
        self.configure(values=self.list_items)

    def set_default_values(self):
        self.config(values=self.list_items)

    def _sleep_to_display_prompt(self):
        time.sleep(30)
        self.set(self.prompt_text)
        self.sleeping_thread = None


class BetterCanvas(tk.Canvas):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def yview_scroll(self, *args):
        if super().yview() == (0.0, 1.0):
            super().yview_moveto('1.0')
            return
        super().yview_scroll(*args)


class EntryBoxWithLabel(ttk.Frame):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cus_port = ttk.Entry(
            self, width=8, name="cus_entry"
        )
        self.widget_label = ttk.Label(self, text="CUS Port", name="cus_entry_label",)
        self.cus_port.grid(row=0, column=1)
        self.widget_label.grid(row=0, column=0, padx=(0, 10))
        self.entry = self.register(self.validate_entry)
        self.cus_port.config(validate='key', validatecommand=(self.entry, '%P'))

    def config(self, *args, **kwargs):
        self.cus_port.config(*args, **kwargs)

    def set(self, *args, **kwargs):
        self.cus_port.set(*args, **kwargs)

    def insert(self, start, txt):
        self.cus_port.insert(start, txt)

    def delete(self, start, end):
        self.cus_port.delete(start, end)

    def get_text(self):
        return self.cus_port.get()

    @staticmethod
    def validate_entry(inp):  #
        if any((re.fullmatch(r'\d\-\d\.\d', inp),  re.fullmatch(r'\d\-\d\.', inp), re.fullmatch(r'\d\-\d', inp),
               re.fullmatch(r'\d\-', inp), re.fullmatch(r'\d', inp))):
            return True
        elif inp == "":
            return True
        else:
            return False


class TextScrollCombo(tk.LabelFrame):

    def __init__(self, *args, **kwargs):

        super().__init__(*args, **kwargs)

    # ensure a consistent GUI size
        self.grid(column=3, row=0, sticky=tk.W, rowspan=2, padx=10)
        self.grid_propagate(False)
    # implement stretchability
        self.grid_rowconfigure(0, weight=1)
        self.grid_columnconfigure(0, weight=1)

    # create a Text widget
        self.txt = tk.Text(self)
        self.txt.grid(row=0, column=0, sticky="nsew", padx=2, pady=2)

    # create a Scrollbar and associate it with txt
        scrollb = ttk.Scrollbar(self, command=self.txt.yview)
        scrollb.grid(row=0, column=1, sticky='nsew')
        self.txt['yscrollcommand'] = scrollb.set

    def insert(self, where, txt):
        self.txt.insert(where, txt)

    def delete(self, _from, to):
        self.txt.delete(_from, to)


class Tooltip:

    def __init__(self, widget,
                 *,
                 bg='#FFFFEA',
                 pad=(5, 3, 5, 3),
                 text='widget info',
                 waittime=400,
                 wraplength=250):

        self.waittime = waittime  # in miliseconds, originally 500
        self.wraplength = wraplength  # in pixels, originally 180
        self.widget = widget
        self.text = text
        self.widget.bind("<Enter>", self.onEnter)
        self.widget.bind("<Leave>", self.onLeave)
        self.widget.bind("<ButtonPress>", self.onLeave)
        self.bg = bg
        self.pad = pad
        self.id = None
        self.tw = None

    def onEnter(self, event=None):
        self.schedule()

    def onLeave(self, event=None):
        self.unschedule()
        self.hide()

    def schedule(self):
        self.unschedule()
        self.id = self.widget.after(self.waittime, self.show)

    def unschedule(self):
        id_ = self.id
        self.id = None
        if id_:
            self.widget.after_cancel(id_)

    def show(self):
        def tip_pos_calculator(widget, label,
                               *,
                               tip_delta=(10, 5), pad=(5, 3, 5, 3)):

            w = widget

            s_width, s_height = w.winfo_screenwidth(), w.winfo_screenheight()

            width, height = (pad[0] + label.winfo_reqwidth() + pad[2],
                             pad[1] + label.winfo_reqheight() + pad[3])

            mouse_x, mouse_y = w.winfo_pointerxy()

            x1, y1 = mouse_x + tip_delta[0], mouse_y + tip_delta[1]
            x2, y2 = x1 + width, y1 + height

            x_delta = x2 - s_width
            if x_delta < 0:
                x_delta = 0
            y_delta = y2 - s_height
            if y_delta < 0:
                y_delta = 0

            offscreen = (x_delta, y_delta) != (0, 0)

            if offscreen:

                if x_delta:
                    x1 = mouse_x - tip_delta[0] - width

                if y_delta:
                    y1 = mouse_y - tip_delta[1] - height

            offscreen_again = y1 < 0  # out on the top

            if offscreen_again:
                # No further checks will be done.

                # TIP:
                # A further mod might automagically augment the
                # wraplength when the tooltip is too high to be
                # kept inside the screen.
                y1 = 0

            return x1, y1

        bg = self.bg
        pad = self.pad
        widget = self.widget

        # creates a toplevel window
        self.tw = tk.Toplevel(widget)

        # Leaves only the label and removes the app window
        self.tw.wm_overrideredirect(True)

        win = tk.Frame(self.tw,
                       background=bg,
                       borderwidth=0)
        label = tk.Label(win,
                         text=self.text,
                         justify=tk.LEFT,
                         background=bg,
                         relief=tk.SOLID,
                         borderwidth=0,
                         wraplength=self.wraplength)

        label.grid(padx=(pad[0], pad[2]),
                   pady=(pad[1], pad[3]),
                   sticky=tk.NSEW)
        win.grid()

        x, y = tip_pos_calculator(widget, label)

        self.tw.wm_geometry("+%d+%d" % (x, y))

    def hide(self):
        tw = self.tw
        if tw:
            tw.destroy()
        self.tw = None
